typedef enum { N_INT, N_ADD, N_IF } NodeKind;

struct Node { NodeKind kind; struct Node *kids[3]; int nkids; };
struct Add { struct Node base; int op; };          /* base first: castable */
struct If  { struct Node base; };

static void walk(struct Node *n, void (*f)(struct Node *)) {
    f(n);
    for (int i = 0; i < n->nkids; i++) walk(n->kids[i], f);
}
